// Flat list for search/filter, deduped by id
const _seen = new Set();
export const ALL_PROBLEMS = Object.entries(ROADMAP_PROBLEMS).flatMap(([topic, problems]) =>
  problems
    .filter(p => { const k = p.id + topic; if (_seen.has(k)) return false; _seen.add(k); return true; })
    .map(p => ({ ...p, topic }))
);

export const TOPICS = Object.keys(ROADMAP_PROBLEMS);

